const crypto = require('crypto');
const secret = $env.PORTAL_TOKEN_SECRET;
if (!secret || secret.length < 32) throw new Error('PORTAL_TOKEN_SECRET debe configurarse con al menos 32 caracteres aleatorios.');
const base = String($env.VRM_PORTAL_URL || '').replace(/\/$/, '');
if (!base) throw new Error('VRM_PORTAL_URL debe apuntar a la URL pública del frontend terminada en /portal.');
const due = $('Find Due Vendors').all().map(i => i.json);
return $input.all().map(it => {
  const a = it.json;
  const v = due.find(d => d.id === a.vendor_id) || {};
  const payload = Buffer.from(JSON.stringify({
    aid: a.assessment_id, vid: a.vendor_id, exp: Date.now() + 30 * 86400000
  })).toString('base64url');
  const sig = crypto.createHmac('sha256', secret).update(payload).digest('base64url');
  return { json: {
    vendor_id: a.vendor_id, assessment_id: a.assessment_id, legal_name: v.legal_name,
    email: v.email || null, link: base + '/assessment/' + payload + '.' + sig
  }};
});

const escapeHtml = (value) => String(value || '').replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[c]));
return $('Sign Portal Link').all()
  .map(entry => entry.json)
  .filter(item => item.email && item.link)
  .map(item => ({
    json: {
      to: item.email,
      subject: 'Evaluación de seguridad de proveedores - VRM',
      html: '<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;padding:24px;color:#0f172a">' +
        '<h2>Evaluación de seguridad de proveedores</h2>' +
        '<p>Hola,</p>' +
        '<p>Se solicita completar la evaluación de seguridad de <strong>' + escapeHtml(item.legal_name) + '</strong>.</p>' +
        '<p>Utiliza el siguiente enlace seguro, válido durante 30 días y de un solo uso:</p>' +
        '<p><a href="' + escapeHtml(item.link) + '" style="display:inline-block;padding:12px 18px;background:#0891b2;color:#fff;text-decoration:none;border-radius:6px">Completar evaluación</a></p>' +
        '<p style="font-size:12px;color:#64748b">Si no esperabas esta solicitud, contacta al equipo responsable de gestión de proveedores.</p>' +
        '</div>'
    }
  }));
